static inline const char* PicoStatusName(uint32_t code) {
  if (auto e = PicoStatusLookup(code)) return e->name;
  return "PICO_STATUS_UNKNOWN";
}

static inline const char* PicoStatusDescription(uint32_t code) {
  if (auto e = PicoStatusLookup(code)) return e->description;
  return "";
}
